from __future__ import annotations

import calendar
import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET_DIR = Path("/app/dataset")


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATASET_DIR / name).open(newline="", encoding="utf-8") as file:
        return list(csv.DictReader(file))


def _parse_valid_date(value: str) -> date | None:
    """Return None for impossible dates instead of silently moving their month."""
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        return None


def _first_weekday_of_month(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_month(work_date: date, billing_weekday: int) -> date:
    """Identify a period by its first occurrence of the billing weekday."""
    start = _first_weekday_of_month(
        work_date.year, work_date.month, billing_weekday
    )
    if work_date >= start:
        return start

    if work_date.month == 1:
        previous_year, previous_month = work_date.year - 1, 12
    else:
        previous_year, previous_month = work_date.year, work_date.month - 1
    return _first_weekday_of_month(
        previous_year, previous_month, billing_weekday
    )


def _task_ids(value: str) -> list[int]:
    # This also repairs lists whose only defect is a missing square bracket.
    return [int(item) for item in re.findall(r"\d+", value or "")]


def answer() -> dict[str, list[int]]:
    employees = _read_csv("employees.csv")
    tasks = _read_csv("tasks.csv")
    timesheet = _read_csv("timesheet.csv")

    hourly_rates = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in employees
        if row.get("PESEL") and Decimal(row["hourly_rate"]) >= 0
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in tasks
    }

    dated_rows: list[tuple[date, dict[str, str]]] = []
    for row in timesheet:
        work_date = _parse_valid_date(row.get("date", ""))
        if work_date is not None:
            dated_rows.append((work_date, row))

    if not dated_rows:
        return {pesel: [] for pesel in hourly_rates}

    # The earliest valid record fixes the salary-collection weekday for all
    # employees. Each billing month starts on its first such weekday.
    billing_weekday = min(work_date for work_date, _ in dated_rows).weekday()

    totals: dict[str, dict[date, Decimal]] = defaultdict(
        lambda: defaultdict(Decimal)
    )
    seen_shifts: set[tuple[str, ...]] = set()

    for work_date, row in dated_rows:
        pesel = row.get("employee_id", "")
        if pesel not in hourly_rates:
            # A timesheet PESEL absent from the employee register has no
            # trustworthy identity or hourly rate.
            continue

        # The file contains repeated shifts with a new row id. All business
        # fields are identical, so retain only one copy.
        duplicate_key = tuple(
            row.get(field, "") for field in row.keys() if field != "id"
        )
        if duplicate_key in seen_shifts:
            continue
        seen_shifts.add(duplicate_key)

        try:
            hours = Decimal(row["hours_worked"])
        except (KeyError, TypeError, ValueError):
            continue
        if hours < 0 or hours > Decimal(24):
            continue

        bonus = sum(
            (task_pay[task_id] for task_id in _task_ids(row.get("performed_tasks", ""))
             if task_id in task_pay),
            Decimal(0),
        )
        period = _billing_month(work_date, billing_weekday)
        totals[pesel][period] += hours * hourly_rates[pesel] + bonus

    result: dict[str, list[int]] = {}
    for pesel in hourly_rates:
        result[pesel] = [
            int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for _, amount in sorted(totals.get(pesel, {}).items())
        ]
    return result


if __name__ == "__main__":
    with Path("/app/answer.json").open("w", encoding="utf-8") as file:
        json.dump(answer(), file, default=list)

