            dated_rows.append((work_date, row))

    if not dated_rows:
        return {pesel: [] for pesel in hourly_rates}

    # The earliest valid record fixes the salary-collection weekday for all
    # employees. Each billing month starts on its first such weekday.
    billing_weekday = min(work_date for work_date, _ in dated_rows).weekday()

    totals: dict[str, dict[date, Decimal]] = defaultdict(
        lambda: defaultdict(Decimal)
    )
    seen_shifts: set[tuple[str, ...]] = set()

    for work_date, row in dated_rows:
        pesel = row.get("employee_id", "")
        if pesel not in hourly_rates:
            # A timesheet PESEL absent from the employee register has no
            # trustworthy identity or hourly rate.
            continue

        # The file contains repeated shifts with a new row id. All business
        # fields are identical, so retain only one copy.
        duplicate_key = tuple(
            row.get(field, "") for field in row.keys() if field != "id"
        )
        if duplicate_key in seen_shifts:
            continue
        seen_shifts.add(duplicate_key)

        try:
            hours = Decimal(row["hours_worked"])
        except (KeyError, TypeError, ValueError):
            continue
        if hours < 0 or hours > Decimal(24):
            continue

        bonus = sum(
            (task_pay[task_id] for task_id in _task_ids(row.get("performed_tasks", ""))
             if task_id in task_pay),
            Decimal(0),
        )
        period = _billing_month(work_date, billing_weekday)
        totals[pesel][period] += hours * hourly_rates[pesel] + bonus

    result: dict[str, list[int]] = {}
    for pesel in hourly_rates:
        result[pesel] = [
            int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for _, amount in sorted(totals.get(pesel, {}).items())
        ]
    return result


